; Rosetta OS PRO-E v0.4b: SYNTH EDIT, Juno-style macro editing of the CK-34 LA tone, menus like the D-70 Rosetta OS.
; CURSOR on the main screen opens it (v0.4b's TRANSPOSE + MELODY INT combo lost to the TRANSPOSE hold page). Levels: 0 = page list, 1 = parameter list, 2 = editing a value.
; TEMPO dial scrolls / changes, CURSOR = enter, PARAMETER = back (out of SYNTH EDIT from the page list),
; BANK 1-8 = jump to page 1-8. Code lives in IC7 upper half bank 5 (PA6 = 1), tables are generated by build_v04b.py.
;
; On entry the part's timbre temp (246 bytes) is read back from the CK-34 with RQ1 into WORK (SCI receiver on
; only while waiting). Every edit changes WORK and sends one DT1 per changed byte, so the CK-34 hears it at once.
; Macro parameters act on every active partial: REL items move each partial's value by the dial step (the tone's
; own balance stays), ABS items set the same value on all of them.

; ---- stock addresses ----
KEYCODE  = $2648
KEYSTATE = $245F        ; byte 1 bit 0 = TRANSPOSE ($08), bit 1 = MELODY INT ($09)
LEDS0    = $0B          ; $0B.4/.5 = MIDI / PARAMETER menu open
MENUS    = $5E          ; $5E.6 = REVERB menu (page $0D, borrowed while editing)
DEMO     = $5D          ; bit 7 = demo playing
TIMEOUT  = $19          ; bit 7 = no message timeout
TRHOLD   = $2D64        ; TRANSPOSE hold timer
PAGEID   = $2662        ; page handler = $FA78 + 3 * (page - $0C)
DLOW     = $51
DHIGH    = $52
DVAL     = $53
DSTEP    = $54
DCNT     = $55
DLOCK    = $2674
LINE1P   = $2665
LINE2P   = $2667
WINFULL  = $D582
DRAW     = $D5AB
SENDCK   = $E82E        ; A -> CK-34 TX ring (keeps A, clobbers B and X)
SCCR2    = $102D
SCSR     = $102E
SCDR     = $102F
K_PARAM  = $05
K_CURSOR = $5D
K_BANK1  = $38

T_NUM    = 0
T_SGN    = 1
T_LIST   = 2
T_PCM    = 3
T_WAVE   = 4
T_PART   = 5
F_ABS    = 1
IT_TYPE  = 0
IT_MAX   = 1
IT_AUX   = 2
IT_FLAGS = 3
IT_N     = 4
IT_OFF   = 5
IT_LABEL = 11
PG_FLAGS = 11
PG_N     = 12
PG_IDX   = 13

        org CODE
; entry from the RAM trampoline: A = 0 key event (B = $80 press / 0 release), A = 1 page-$0D tick
; return C = 1: handled, C = 0: run the stock code
entry:  tsta
        bne tick
        ldaa EDIT
        bne inedit
        tstb
        bpl pass
        ldaa KEYCODE            ; CURSOR opens it: no LED, and stock only uses it inside its menus
        cmpa #K_CURSOR
        bne pass
tryent: ldaa LEDS0              ; only from the main screen: no menu, no demo
        anda #$30
        bne pass
        ldaa MENUS
        anda #$7E
        bne pass
        ldaa DEMO
        bmi pass
        jsr enter
        sec
        rts
pass:   clc
        rts
inedit: ldaa MENUS              ; something else closed our page: let go
        anda #$40
        bne ie_ok
        clr EDIT
        clc
        rts
ie_ok:  tstb
        bpl eat                 ; releases are swallowed
        ldaa KEYCODE
        cmpa #K_PARAM
        bne ie1
        jsr k_back
        bra eat
ie1:    cmpa #K_CURSOR
        bne ie2
        jsr k_enter
        bra eat
ie2:    cmpa #K_BANK1
        bcs eat
        cmpa #K_BANK1+7
        bhi eat
        suba #K_BANK1
        jsr k_bank
eat:    sec
        rts

tick:   ldaa EDIT
        beq pass                ; the real REVERB menu
        ldaa DVAL
        suba #50
        beq t_done
        staa DELTA
        ldaa #50
        staa DVAL
        jsr k_dial
t_done: sec
        rts

; ---------------- open / close ----------------
enter:  ldaa #1
        staa EDIT
        nop                     ; (v0.4c: clr TRHOLD here armed the TRANSPOSE hold timer: $00 = fire now, $FF = idle)
        nop
        nop
        bset MENUS,#$40         ; page $0D: dial routed to our tick
        bset TIMEOUT,#$80       ; no message timeout
        ldaa #$0D
        staa PAGEID
        ldd #$0164              ; dial range 0..100, centre 50
        std DLOW
        clr LVL
        clr SEL
        clr ROW
        jsr dialnav
        jsr readtone
        jmp redraw

leave:  clr EDIT
        bclr MENUS,#$40
        clr TIMEOUT             ; next tick: stock timeout path restores the main screen + tempo dial
        ldaa #$0C
        staa DLOCK
        rts

dialnav: ldaa #8                ; pulses per step: lists like the stock MIDI menu
        bra dset
dialval: ldaa #2                ; values like the tempo dial
dset:   staa DSTEP
        staa DCNT
        ldaa #50
        staa DVAL
        ldaa #$0C
        staa DLOCK              ; 240 ms dial lock like the stock menus
        rts

; ---------------- keys ----------------
k_back: ldaa LVL                ; PARAMETER: one level up
        beq leave
        deca
        staa LVL
        jsr dialnav
        jmp redraw

k_enter: ldaa LVL               ; CURSOR: one level down (level 2 -> back to 1)
        bne ke1
        clr ROW
        ldaa #1
        staa LVL
        jsr pageptr
        ldaa PG_FLAGS,x         ; LIVE page: straight into editing
        anda #1
        beq ke_nav
ke_val: ldaa #2
        staa LVL
        jsr dialval
        jmp redraw
ke1:    cmpa #1
        beq ke_val
        ldaa #1
        staa LVL
ke_nav: jsr dialnav
        jmp redraw

k_bank: cmpa #NPAGES            ; BANK n: page n
        bcc kb_x
        staa SEL
        clr LVL
        bra k_enter
kb_x:   rts

k_dial: ldaa LVL
        bne kd1
        ldaa #NPAGES-1
        staa MAXV
        ldab SEL
        jsr addclamp
        stab SEL
        jmp redraw
kd1:    cmpa #1
        bne kd2
        jsr pageptr
        ldaa PG_N,x
        deca
        staa MAXV
        ldab ROW
        jsr addclamp
        stab ROW
        jmp redraw
kd2:    jsr change
        jmp redraw

; B = clamp(B + DELTA, 0, MAXV); DELTA is signed
addclamp:
        clra
        std T16
        ldab DELTA
        clra
        tstb
        bpl ac1
        coma
ac1:    addd T16
        bmi ac0
        tsta
        bne acm
        cmpb MAXV
        bhi acm
        rts
ac0:    clrb
        rts
acm:    ldab MAXV
        rts

; ---------------- tables ----------------
pageptr: ldaa SEL               ; X = page record
        ldab #20
        mul
        addd #PAGES
        xgdx
        rts

itemptr: jsr pageptr            ; IT = X = item record of (SEL, ROW)
        ldab ROW
        abx
        ldaa PG_IDX,x
        ldab #20
        mul
        addd #ITEMS
        std IT
        xgdx
        rts

; MASK = active partials (partial mute bits, none = all four), REFP = lowest active partial
actmask: ldaa WORK+$0C
        anda #$0F
        bne am1
        ldaa #$0F
am1:    staa MASK
        clrb
am2:    lsra
        bcs am3
        incb
        bra am2
am3:    stab REFP
        rts

; A = partial -> X = its 58 bytes in WORK, IDXB = its timbre-temp index
pbase:  ldab #58
        mul
        addd #14
        std IDXB
        addd #WORK
        xgdx
        rts

; next active partial after PNUM: C = 0 and X / IDXB set, C = 1 when done
pnext:  ldaa PNUM
        cmpa #4
        bcc pn_end
        inc PNUM
        ldab MASK
        tsta
pn_sh:  beq pn_t
        lsrb
        deca
        bra pn_sh
pn_t:   lsrb
        bcc pnext
        ldaa PNUM
        deca
        jsr pbase
        clc
        rts
pn_end: sec
        rts

; A = value of the item IT, read from the reference partial
getval: ldx IT
        ldab IT_TYPE,x
        cmpb #T_PART
        bne gv1
        ldaa PARTIX
        rts
gv1:    jsr actmask
        ldaa REFP
        jsr pbase
        ldy IT
        ldab IT_TYPE,y
        cmpb #T_PCM
        bne gv2
        ldaa 4,x                ; WG waveform bit 1 = PCM bank
        anda #2
        asla
        asla
        asla
        asla
        asla
        asla
        oraa 5,x
        rts
gv2:    cmpb #T_WAVE
        bne gv3
        ldaa 4,x                ; bit 0 = SQUARE / SAW
        anda #1
        rts
gv3:    ldab IT_OFF,y
        abx
        ldaa 0,x
        rts

; ---------------- editing ----------------
change: jsr itemptr
        ldab IT_TYPE,x
        cmpb #T_PART
        bne ch1
        ldaa #2
        staa MAXV
        ldab PARTIX
        jsr addclamp
        cmpb PARTIX
        beq ch_x
        stab PARTIX
        jmp readtone
ch_x:   rts
ch1:    jsr getval              ; A = current value (sets MASK)
        ldx IT
        ldab IT_FLAGS,x
        andb #F_ABS
        beq ch_rel
        ldab IT_MAX,x           ; ABS: one new value for every active partial
        stab MAXV
        tab
        jsr addclamp
        stab NEWV
        clr PNUM
ca_lp:  jsr pnext
        bcs ch_x
        jsr setabs
        bra ca_lp
ch_rel: clr KIX                 ; REL: every offset of the item, every active partial, moved by DELTA
cr_k:   ldx IT
        ldab KIX
        cmpb IT_N,x
        bcc ch_x
        abx
        ldab IT_OFF,x
        stab OFFS
        ldx #PMAX
        abx
        ldaa 0,x
        staa MAXV
        clr PNUM
cr_p:   jsr pnext
        bcs cr_nk
        stx PB2
        ldab OFFS
        abx
        ldab 0,x
        jsr addclamp
        tba
        ldx PB2
        ldab OFFS
        jsr putb
        bra cr_p
cr_nk:  inc KIX
        bra cr_k

; X = partial, IDXB = its index: write NEWV the item's way
setabs: ldy IT
        ldab IT_TYPE,y
        cmpb #T_PCM
        bne sa1
        ldaa NEWV               ; value bit 7 -> waveform bit 1 (bank), bits 0-6 -> PCM wave
        anda #$80
        lsra
        lsra
        lsra
        lsra
        lsra
        lsra
        staa TMP
        ldaa 4,x
        anda #$FD
        oraa TMP
        ldab #4
        jsr putb
        ldaa NEWV
        anda #$7F
        ldab #5
        jmp putb
sa1:    cmpb #T_WAVE
        bne sa2
        ldaa 4,x
        anda #$FE
        oraa NEWV
        ldab #4
        jmp putb
sa2:    ldab IT_OFF,y
        ldaa NEWV
                                ; falls into putb
; A = value, B = offset in the partial X: store it and send it if it changed (X kept)
putb:   stx PB
        abx
        cmpa 0,x
        beq pb_same
        staa 0,x
        staa VAL
        clra
        addd IDXB
        std IDX
        jsr dt1
pb_same: ldx PB
        rts

; DT1 of one byte: timbre temp index IDX = VAL, to the part's channel
dt1:    ldaa #$F0
        jsr SENDCK
        ldaa #$41
        jsr SENDCK
        ldaa DEV
        jsr SENDCK
        ldaa #$16
        jsr SENDCK
        ldaa #$12
        jsr SENDCK
        ldaa #$02
        staa SUM
        jsr SENDCK
        ldd IDX                 ; address mid = IDX >> 7
        asld
        staa TMP
        adda SUM
        staa SUM
        ldaa TMP
        jsr SENDCK
        ldaa IDX+1              ; address lo = IDX & $7F
        anda #$7F
        staa TMP
        adda SUM
        staa SUM
        ldaa TMP
        jsr SENDCK
        ldaa VAL
        adda SUM
        staa SUM
        ldaa VAL
        jsr SENDCK
        ldaa SUM                ; Roland checksum
        nega
        anda #$7F
        jsr SENDCK
        ldaa #$F7
        jmp SENDCK

; ---------------- read the tone back (RQ1) ----------------
readtone:
        ldx #devtab
        ldab PARTIX
        abx
        ldaa 0,x
        staa DEV
        ldx #SCCR2
        bset 0,x,#$04           ; receiver on
        ldaa SCSR               ; flush
        ldaa SCDR
        ldaa SCSR
        ldaa SCDR
        ldx #rq1
rt_s:   stx PB
        ldaa 0,x
        cmpa #$FF
        bne rt_s1
        ldaa DEV
rt_s1:  jsr SENDCK
        ldx PB
        inx
        cpx #rq1+13
        bne rt_s
        clr VALID
        ldab #40                ; up to 40 stray bytes before the F0
rt_f0:  pshb
        jsr rxbyte
        pulb
        bcs rt_fail
        cmpa #$F0
        beq rt_hd
        decb
        bne rt_f0
        bra rt_fail
rt_hd:  ldx #rphdr
rt_h1:  stx PB
        jsr rxbyte
        bcs rt_fail
        ldx PB
        ldab 0,x
        cmpb #$FF
        bne rt_h2
        ldab DEV
rt_h2:  cba
        bne rt_fail
        inx
        cpx #rphdr+7
        bne rt_h1
        ldaa #$02
        staa SUM
        ldx #WORK
rt_d:   stx PB
        jsr rxbyte
        bcs rt_fail
        tsta
        bmi rt_fail
        ldx PB
        staa 0,x
        adda SUM
        staa SUM
        inx
        cpx #WORK+246
        bne rt_d
        jsr rxbyte              ; checksum
        bcs rt_fail
        adda SUM
        anda #$7F
        bne rt_fail
        jsr rxbyte              ; F7
        bcs rt_fail
        cmpa #$F7
        bne rt_fail
        inc VALID
        bra rt_end
rt_fail: ldx #DEFTONE           ; no reply: edit a known tone instead of garbage
        ldy #WORK
rt_cp:  ldaa 0,x
        staa 0,y
        inx
        iny
        cpy #WORK+246
        bne rt_cp
rt_end: ldx #SCCR2
        bclr 0,x,#$04           ; receiver off again (stock: TX only)
        rts

; A = next received byte, C = 1 on timeout (about 0.5 s)
rxbyte: ldx #0
rx_lp:  ldaa SCSR
        bita #$20
        bne rx_got
        dex
        bne rx_lp
        sec
        rts
rx_got: ldaa SCDR
        clc
        rts

; ---------------- screen ----------------
redraw: ldaa LVL
        bne rd1
        ldx #ttl_ok             ; page list: "SYNTH EDIT  SOLO" / " FILTER     4/9"
        ldaa VALID
        bne rd0
        ldx #ttl_nr
rd0:    ldy #LINE1
        ldab #12
        jsr copyn
        jsr partnm
        ldy #LINE2
        ldaa #' '
        staa 0,y
        iny
        jsr pageptr
        ldab #11
        jsr copyn
        ldaa #' '
        staa 0,y
        ldaa SEL
        adda #'1'
        staa 1,y
        ldaa #'/'
        staa 2,y
        ldaa #'0'+NPAGES
        staa 3,y
        bra rd_out
rd1:    jsr pageptr             ; parameter: "FILTER      SOLO" / "CUTOFF   >    64"
        ldy #LINE1
        ldab #11
        jsr copyn
        ldaa #' '
        staa 0,y
        iny
        jsr partnm
        jsr itemptr
        ldab #IT_LABEL
        abx
        ldy #LINE2
        ldab #9
        jsr copyn
        ldaa #' '
        ldab LVL
        cmpb #2
        bne rd1a
        ldaa #'>'
rd1a:   staa 0,y
        iny
        sty VPTR
        jsr fmtval
rd_out: ldd #LINE1
        std LINE1P
        ldd #LINE2
        std LINE2P
        jsr WINFULL
        jmp DRAW

copyn:  ldaa 0,x                ; B bytes X -> Y (both advance)
        staa 0,y
        inx
        iny
        decb
        bne copyn
        rts

partnm: ldaa PARTIX             ; 4-char part name at Y
        asla
        asla
        ldx #pnames
        tab
        abx
        ldab #4
        jmp copyn

; value of IT as 6 chars at VPTR
fmtval: jsr getval
        staa VAL
        ldy VPTR
        ldx IT
        ldab IT_TYPE,x
        cmpb #T_NUM
        bne fv1
        ldab VAL
        clra
        jmp fmtnum
fv1:    cmpb #T_SGN
        bne fv2
        ldab VAL
        subb IT_AUX,x
        beq fv1z
        bmi fv1n
        ldaa #'+'
        jmp fmtnum
fv1n:   negb
        ldaa #'-'
        jmp fmtnum
fv1z:   clra
        jmp fmtnum
fv2:    cmpb #T_PCM
        bne fv3
        ldab VAL                ; "1- 12": bank - wave
        andb #$7F
        incb
        clra
        jsr fmtnum
        ldy VPTR
        ldaa VAL
        rola
        ldaa #'1'
        adca #0
        staa 0,y
        ldaa #'-'
        staa 1,y
        rts
fv3:    ldaa IT_AUX,x           ; list types: 6-char names
        asla
        ldx #listtab
        tab
        abx
        ldx 0,x
        ldaa VAL
        ldab #6
        mul
        abx
        ldab #6
        jmp copyn

; B = number, A = sign char (0 = none): 6 chars right-aligned at Y
fmtnum: staa SIGN
        stab MAGN
        sty T16
        ldx T16
        ldab #6
        ldaa #' '
fn_sp:  staa 0,x
        inx
        decb
        bne fn_sp
        dex
        ldab MAGN
fn_dg:  stx PB
        clra
        ldx #10
        idiv
        addb #'0'
        stx QT
        ldx PB
        stab 0,x
        dex
        ldab QT+1
        bne fn_dg
        ldaa SIGN
        beq fn_x
        staa 0,x
fn_x:   rts

; ---------------- boot ----------------
; called by BOOTCOPY in IC4 with bank 5 + PA6 high: copy the RAM trampoline, then return through BOOTRET in RAM
boot8:  ldx #TRAMP_IMG
        ldy #RAMBASE
        ldab #TRAMP_LEN
b8_lp:  ldaa 0,x
        staa 0,y
        inx
        iny
        decb
        bne b8_lp
        clr EDIT
        clr PARTIX
        ldx #splash             ; ~0.6 s "SYNTH READY": proves the PA6 half switch + boot copy on hardware
        ldy #LINE1
        ldab #32
        jsr copyn
        ldd #LINE1
        std LINE1P
        ldd #LINE2
        std LINE2P
        jsr WINFULL
        jsr DRAW
        ldy #3
        jsr $ED35               ; stock busy delay, Y = 5 is about 1 s
        jmp BOOTRET

rq1:    db $F0,$41,$FF,$16,$11,$02,$00,$00,$00,$01,$76,$07,$F7   ; RQ1 timbre temp, 246 bytes ($FF = device)
rphdr:  db $41,$FF,$16,$12,$02,$00,$00
devtab: db $03,$02,$01                                          ; SOLO ch 4, LOWER ch 3, MANUAL BASS ch 2
pnames: db "SOLOLOWRBASS"
ttl_ok: db "SYNTH EDIT  "
ttl_nr: db "NO REPLY    "
splash: db "  SYNTH  READY  "
        db " CURSOR = OPEN  "
